function renderMotionM1Samples() {
  const lane = $("#motionM1SampleLane");
  const grid = $("#motionM1SampleGrid");
  const summary = $("#motionM1SampleSummary");
  if (!lane || !grid || !summary) return;
  const { samples, isDraftPreview } = getMotionM1SampleCatalog();
  lane.hidden = samples.length === 0;
  if (!samples.length) {
    grid.innerHTML = "";
    summary.textContent = "";
    return;
  }
  const playbackPreference = getMotionPlaybackPreference();
  summary.textContent = isDraftPreview
    ? `로컬 M1 초안 ${samples.length}개 · 해부학과 움직임을 분리해 검토하는 미리보기입니다.`
    : `검수 완료 M1 샘플 ${samples.length}개 · 모두 클릭할 때만 재생됩니다.`;
  grid.innerHTML = samples.map((sample) => renderMotionM1SampleCard(sample, playbackPreference)).join("");
  syncMotionM1SamplePlaybackEvents(grid);
}

function isMotionM2Published(sample) {
  const publicationStatus = sample?.review?.publication?.status;
  const publicationPassed = publicationStatus === "published" && sample?.reviewStatus === "published";
  if (!publicationPassed) return false;
  const requiredReviewKeys =
    sample?.motionClass === "generative-i2v"
      ? [
          "sourceIntegrity",
          "workflowIntegrity",
          "frameAnatomy",
          "identityContinuity",
          "limbCountContinuity",
          "motionPlausibility",
          "backgroundIntegrity",
          "cameraIntegrity",
          "temporalIntegrity",
          "responsive",
        ]
      : [
          "frameAnatomy",
          "maskIntegrity",
          "cleanPlateIntegrity",
          "motionPlausibility",
          "backgroundIntegrity",
          "temporalIntegrity",
          "responsive",
        ];
  const reviewPassed = requiredReviewKeys.every((key) => sample.review?.[key]?.status === "supported");
  const file = sample?.file;
  const filePassed =
    /^[a-f0-9]{64}$/.test(file?.sha256 || "") &&
    Number.isFinite(file?.bytes) && file.bytes > 0 &&
    Number.isFinite(file?.width) && file.width > 0 &&
    Number.isFinite(file?.height) && file.height > 0 &&
    Number.isFinite(file?.durationSeconds) && file.durationSeconds > 0 &&
    Number.isFinite(file?.fps) && file.fps > 0 &&
    Number.isFinite(file?.frameCount) && file.frameCount > 0 &&
    typeof file?.codec === "string" && file.codec.length > 0 &&
    typeof file?.pixelFormat === "string" && file.pixelFormat.length > 0 &&
    file?.audio === false;
  return reviewPassed && filePassed;
}

function getMotionM2CreditLabel(credits) {
  if (typeof credits === "string") return credits.trim();
  if (Array.isArray(credits)) {
    return credits.filter((credit) => typeof credit === "string" && credit.trim()).join(" · ");
  }
  if (credits && typeof credits === "object") {
    return Object.values(credits)
      .filter((credit) => typeof credit === "string" && credit.trim())
      .join(" · ");
  }
  return "";
}

function getMotionM2SampleCatalog() {
  const globalSamples = typeof motionM2Samples !== "undefined" ? motionM2Samples : window.motionM2Samples;
  const controlledCatalog =
    typeof motionM2SampleCatalog !== "undefined" ? motionM2SampleCatalog : window.motionM2SampleCatalog;
  const i2vCatalog =
    typeof motionM2I2VSampleCatalog !== "undefined"
      ? motionM2I2VSampleCatalog
      : window.motionM2I2VSampleCatalog;
  const baseCatalog = controlledCatalog || globalSamples;
  const controlledSamples = Array.isArray(baseCatalog) ? baseCatalog : baseCatalog?.samples;
  const i2vSamples = Array.isArray(i2vCatalog) ? i2vCatalog : i2vCatalog?.samples;
  const isLocalHost = ["localhost", "127.0.0.1"].includes(window.location.hostname);
  const requestedPreview = new URLSearchParams(window.location.search).get("motionPreview");
  const previewMode = isLocalHost && ["m2", "i2v"].includes(requestedPreview) ? requestedPreview : "";
  const isDraftPreview = Boolean(previewMode);
  const sourceSamples = [
    ...(Array.isArray(controlledSamples)
      ? controlledSamples.map((sample) => ({ ...sample, motionCatalogKind: "controlled" }))
      : []),
    ...(previewMode !== "m2" && Array.isArray(i2vSamples)
      ? i2vSamples.map((sample) => ({ ...sample, motionCatalogKind: "i2v" }))
      : []),
  ];
  if (!sourceSamples.length) {
    return { policy: {}, samples: [], isDraftPreview, previewMode };
  }
  const allowedMotionClasses = new Set(["controlled-partial-body", "generative-i2v"]);
  const allowedM2SceneRoles = new Set([
    "solo",
    "foraging-behavior",
    "predator-prey-interaction",
    "environment-event",
  ]);

  const samples = sourceSamples
    .map((sample) => {
      const matchedDino = sample?.taxonId ? getDinoById(sample.taxonId) : null;
      return {
        ...sample,
        taxon: sample?.taxon || sample?.scientificName || "",
        commonName: sample?.commonName || matchedDino?.koreanName || sample?.sceneRoleLabel || sample?.title || "",
        summary: sample?.summary || sample?.description || "",
        evidenceBoundary:
          sample?.evidenceBoundary ||
          sample?.review?.anatomy?.note ||
          "M2 움직임은 해부학 또는 행동의 직접 증거가 아닙니다.",
        credits:
          sample?.credits ||
          [sample?.provenance?.sourceLicense, sample?.provenance?.workflow].filter(Boolean),
        pipelineLabel:
          sample?.pipelineLabel ||
          (sample?.motionCatalogKind === "i2v" ? "생성형 I2V" : "제어형 2D 합성"),
        videoPath: sample?.videoPath || sample?.src || "",
        durationSeconds: sample?.durationSeconds ?? sample?.file?.durationSeconds,
        fps: sample?.fps ?? sample?.file?.fps,
        frameCount: sample?.frameCount ?? sample?.file?.frameCount,
        width: sample?.width ?? sample?.file?.width,
        height: sample?.height ?? sample?.file?.height,
      };
    })
    .filter((sample) => {
      const videoPathIsSafe =
        typeof sample.videoPath === "string" &&
        !sample.videoPath.includes("..") &&
        /^assets\/motion\/m2\/[a-z0-9][a-z0-9./-]*-m2-v[0-9]+\.mp4$/i.test(sample.videoPath);
      return (
        String(sample.motionTier || sample.tier || "").toUpperCase() === "M2" &&
        /^[a-z0-9][a-z0-9-]*$/i.test(sample.id || "") &&
        typeof sample.taxon === "string" && sample.taxon.trim().length > 0 &&
        typeof sample.commonName === "string" && sample.commonName.trim().length > 0 &&
        typeof sample.title === "string" && sample.title.trim().length > 0 &&
        typeof sample.summary === "string" && sample.summary.trim().length > 0 &&
        typeof sample.motionLabel === "string" && sample.motionLabel.trim().length > 0 &&
        allowedM2SceneRoles.has(sample.sceneRole) &&
        typeof sample.sceneRoleLabel === "string" && sample.sceneRoleLabel.trim().length > 0 &&
        typeof sample.evidenceBoundary === "string" && sample.evidenceBoundary.trim().length > 0 &&
        getMotionM2CreditLabel(sample.credits).length > 0 &&
        sample.representativeEligible === false &&
        sample.galleryEligible === false &&
        sample.anatomyEligible === false &&
        allowedMotionClasses.has(sample.motionClass) &&
        (sample.motionCatalogKind === "i2v"
          ? sample.motionClass === "generative-i2v"
          : sample.motionClass === "controlled-partial-body") &&
        isSafeMotionPosterSource(sample.poster) &&
        videoPathIsSafe &&
        Number.isFinite(sample.durationSeconds) && sample.durationSeconds > 0 &&
        Number.isFinite(sample.fps) && sample.fps > 0 &&
        Number.isFinite(sample.frameCount) && sample.frameCount > 0 &&
        Number.isFinite(sample.width) && sample.width > 0 &&
        Number.isFinite(sample.height) && sample.height > 0 &&
        (isDraftPreview || isMotionM2Published(sample))
      );
    });
  return {
    policy: {
      controlled: Array.isArray(baseCatalog) ? {} : baseCatalog?.policy || {},
      i2v: Array.isArray(i2vCatalog) ? {} : i2vCatalog?.policy || {},
    },
    samples,
    isDraftPreview,
    previewMode,
  };
}

function renderMotionM2SampleCard(sample, playbackPreference, isDraftPreview) {
  const conservativeLoading = playbackPreference.reducedMotion || playbackPreference.saveData;
  const isI2V = sample.motionClass === "generative-i2v";
  const published = isMotionM2Published(sample) && !isDraftPreview;
  const tierLabel = isI2V ? "M2 · 생성형 I2V" : "M2 · 큰 부분 움직임";
  const localReviewLabel = isI2V ? "새 I2V 비교 후보" : "기존 제어형 M2 보류";
  const durationLabel = Number(sample.durationSeconds).toFixed(1);
  const playbackNote = playbackPreference.saveData
    ? "데이터 절약 설정 · 눌러야 파일을 불러옵니다"
    : playbackPreference.reducedMotion
      ? "움직임 줄이기 설정 · 직접 재생만 합니다"
      : `자동재생 없음 · 눌러서 ${durationLabel}초 재생`;
  const dimensions = `${sample.width}×${sample.height} · ${sample.fps}fps · ${sample.frameCount}프레임`;
  return `
    <article class="motion-sample-card ${published ? "is-published" : "is-draft"}" data-motion-sample="${escapeHtml(sample.id)}" data-motion-tier="M2" data-motion-pipeline="${escapeHtml(sample.motionCatalogKind)}" data-motion-scene-role="${escapeHtml(sample.sceneRole)}" data-motion-playing-label="${escapeHtml(sample.motionLabel)}">
      <div class="motion-sample-media">
        <video
          id="motionM2Video-${escapeHtml(sample.id)}"
          data-motion-video="${escapeHtml(sample.id)}"
          data-motion-src="${escapeHtml(sample.videoPath)}"
          poster="${escapeHtml(sample.poster)}"
          preload="${conservativeLoading ? "none" : "metadata"}"
          muted
          playsinline
          controlslist="nodownload noremoteplayback"
          disablepictureinpicture
          aria-label="${escapeHtml(sample.title)} 움직임 샘플"
        ></video>
        <button class="motion-play-button" data-motion-play="${escapeHtml(sample.id)}" type="button" aria-controls="motionM2Video-${escapeHtml(sample.id)}">
          <span aria-hidden="true">▶</span>
          눌러서 재생
        </button>
        <span class="motion-tier-badge">${escapeHtml(tierLabel)}</span>
        <span class="motion-scene-badge">${escapeHtml(sample.sceneRoleLabel)}</span>
      </div>
      <div class="motion-sample-body">
        <div class="motion-sample-title-row">
          <div>
            <p class="eyebrow">${escapeHtml(sample.taxon)}</p>
            <h4>${escapeHtml(sample.title)}</h4>
          </div>
          <span class="motion-review-badge ${published ? "ready" : "pending"}">${published ? "M2 공개 검수 완료" : escapeHtml(localReviewLabel)}</span>
        </div>
        <p>${escapeHtml(sample.summary)}</p>
        <dl class="motion-sample-facts">
          <div><dt>공룡</dt><dd>${escapeHtml(sample.commonName)}</dd></div>
          <div><dt>장면 유형</dt><dd>${escapeHtml(sample.sceneRoleLabel)}</dd></div>
          <div><dt>제작 방식</dt><dd>${escapeHtml(sample.pipelineLabel)}</dd></div>
          <div><dt>움직임</dt><dd>${escapeHtml(sample.motionLabel)}</dd></div>
          <div><dt>영상 사양</dt><dd>${escapeHtml(dimensions)}</dd></div>
          <div><dt>근거 경계</dt><dd>${escapeHtml(sample.evidenceBoundary)}</dd></div>
        </dl>
        <p class="motion-playback-note" data-motion-status role="status" aria-live="polite" aria-atomic="true">${escapeHtml(playbackNote)}</p>
        <div class="motion-sample-footer">
          <span>${isI2V ? "M2 I2V" : "M2"} · 해부학 증거 아님 · ${escapeHtml(getMotionM2CreditLabel(sample.credits))}</span>
          <a href="${escapeHtml(sample.videoPath)}" target="_blank" rel="noopener">동영상 파일 열기</a>
        </div>
      </div>
    </article>
  `;
}

function syncMotionM2SamplePlaybackEvents(grid) {
  grid.querySelectorAll('[data-motion-video]').forEach((video) => {
    const card = video.closest("[data-motion-sample]");
    const button = card?.querySelector("[data-motion-play]");
    const status = card?.querySelector("[data-motion-status]");
    if (!card || !button || !status) return;
    video.defaultMuted = true;
    video.muted = true;
    video.addEventListener("play", () => {
      const transferFocus = document.activeElement === button;
      card.classList.add("is-playing");
      button.hidden = true;
      status.textContent = `재생 중 · 소리 없음 · ${card.dataset.motionPlayingLabel}`;
      if (transferFocus) video.focus({ preventScroll: true });
    });
    const markPaused = () => {
      card.classList.remove("is-playing");
      button.hidden = false;
      button.innerHTML = '<span aria-hidden="true">▶</span> 다시 재생';
      status.textContent = video.ended ? "재생 완료 · 원본 포스터로 돌아갈 수 있습니다" : "일시 정지됨";
    };
    video.addEventListener("pause", markPaused);
    video.addEventListener("ended", markPaused);
    video.addEventListener("error", () => {
      card.classList.remove("is-playing");
      card.classList.add("has-error");
      button.hidden = false;
      button.disabled = true;
      button.textContent = "파일 준비 중";
      status.textContent = "동영상 파일을 아직 불러올 수 없습니다. 포스터 이미지는 그대로 볼 수 있습니다.";
    });
  });
}

function renderMotionM2Samples() {
  const lane = $("#motionM2SampleLane");
  const grid = $("#motionM2SampleGrid");
  const summary = $("#motionM2SampleSummary");
  if (!lane || !grid || !summary) return;
  const { samples, isDraftPreview, previewMode } = getMotionM2SampleCatalog();
  lane.hidden = samples.length === 0;
  if (!samples.length) {
    grid.innerHTML = "";
    summary.textContent = "";
    return;
  }
  const playbackPreference = getMotionPlaybackPreference();
  const controlledCount = samples.filter((sample) => sample.motionCatalogKind === "controlled").length;
  const i2vCount = samples.filter((sample) => sample.motionCatalogKind === "i2v").length;
  const sceneRoleSummary = [...new Set(samples.map((sample) => sample.sceneRoleLabel))].join(" · ");
  summary.textContent =
    previewMode === "i2v"
      ? `로컬 M2 비교 · 기존 제어형 ${controlledCount}개 + 새 I2V 후보 ${i2vCount}개 · 직접 눌러 비교합니다.`
      : previewMode === "m2"
        ? `로컬 제어형 M2 ${controlledCount}개 · 보류된 기존 후보만 확인합니다.`
        : `검수 완료 M2 샘플 ${samples.length}개 · ${sceneRoleSummary} · 모두 직접 눌렀을 때만 재생됩니다.`;
  grid.innerHTML = samples
    .map((sample) => renderMotionM2SampleCard(sample, playbackPreference, isDraftPreview))
    .join("");
  syncMotionM2SamplePlaybackEvents(grid);
}

async function toggleMotionSample(button) {
  const card = button.closest("[data-motion-sample]");
  const video = card?.querySelector("[data-motion-video]");
  const status = card?.querySelector("[data-motion-status]");
  if (!video || !status || button.disabled) return;
  if (!video.paused) {
    video.pause();
    return;
  }
  $$('[data-motion-video]').forEach((otherVideo) => {
    if (otherVideo !== video && !otherVideo.paused) otherVideo.pause();
  });
  if (!video.getAttribute("src")) {
    video.src = video.dataset.motionSrc;
    video.load();
  }
  video.controls = true;
  video.tabIndex = 0;
  video.muted = true;
  status.textContent = "동영상을 불러오는 중입니다.";
  try {
    await video.play();
  } catch (error) {
    button.hidden = false;
    status.textContent = "브라우저 재생 버튼을 한 번 더 눌러 주세요.";
  }
}

function getGalleryItems(dino) {
  const bySlot = new Map(getSlottedGalleryImages(dino).map((item) => [item.gallerySlot, item]));
  return Array.from({ length: dino.imageSlots }, (_, index) => {
    const gallerySlot = index + 1;
    const assigned = bySlot.get(gallerySlot);
    if (assigned) return assigned;
    const role = Object.keys(gallerySlotRoleLabels)[index] || "alternate-habitat-behavior";
    const roleLabel = gallerySlotRoleLabels[role];
    return {
      gallerySlot,
      galleryRole: role,
      kind: "생성 예정",
      title: `${gallerySlot}번 슬롯 · ${roleLabel}`,
      body: `${dino.koreanName}의 ${roleLabel} 이미지가 아직 최종 배정되지 않았습니다. 종별 해부학과 팔레트를 유지한 후보만 이 슬롯에 들어갑니다.`,
      source: "Gallery slot generation plan",
      variant: "pending-slot",
    };
  });
}

function matchesClassification(dino, classification = state.classification) {
  if (classification === "all") return true;
  if (classification === "theropoda") return dino.clade === "Theropoda";
  if (classification === "avialae") return dino.clade === "Avialae";
  if (classification === "sauropodomorpha") return dino.clade === "Sauropodomorpha";
  if (classification === "ornithischia") {
    return ornithischianClassificationClades.has(dino.clade);
  }
  if (classification === "pterosauria") return dino.rootClade === "Pterosauria";
  if (classification === "marine-reptilia") return dino.rootClade === "Marine Reptilia";
  if (classification === "synapsida") return dino.rootClade === "Synapsida";
  if (classification === "mammalia") {
    return dino.rootClade === "Mammalia" || dino.clade === "Mammalia";
  }
  if (classification === "cephalopoda") return dino.rootClade === "Mollusca";
  if (classification === "arthropoda") return dino.rootClade === "Arthropoda";
  if (classification === "fishes") {
    return (
      dino.rootClade === "Vertebrata" ||
      dino.rootClade === "Chondrichthyes" ||
      dino.clade === "Placodermi" ||
      dino.clade === "Lamniformes"
    );
  }
  if (classification === "early-dinosaur") return dino.clade === "Saurischia";
  return false;
}

function matchesNonClassificationFilters(dino) {
  const query = state.search.trim().toLowerCase();
  const dietMatches = state.diet === "all" || dino.diet.includes(state.diet);
  const levelMatches =
    state.knowledgeLevel === "all" || dino.knowledgeLevel === Number(state.knowledgeLevel);
  const identityText = [
    dino.name,
    dino.koreanName,
    ...(dino.aliases || []),
    dino.family,
    dino.period,
    dino.region,
    getKnowledgeLevel(dino.knowledgeLevel).short,
    getKnowledgeLevel(dino.knowledgeLevel).label,
  ]
    .join(" ")
    .toLowerCase();
  const rootClade = dino.rootClade || "Dinosauria";
  const taxonomyTerms = [
    rootClade,
    dino.clade,
    cladeMeta[dino.clade],
    ...(taxonomySearchAliases[rootClade] || []),
    ...(taxonomySearchAliases[dino.clade] || []),
  ]
    .filter(Boolean)
    .map((term) => String(term).toLowerCase());
  const queryMatches =
    !query || identityText.includes(query) || taxonomyTerms.some((term) => term.startsWith(query));
  return dietMatches && levelMatches && queryMatches;
}

function getFilteredDinosaurs() {
  return getRealmDinosaurs().filter(
    (dino) => matchesNonClassificationFilters(dino) && matchesClassification(dino),
  );
}

function getRealmDinosaurs(realm = state.atlasRealm) {
  return dinosaurs.filter((dino) => getAtlasRealm(dino) === realm);
}

function getRealmEmptyStateCopy(filteredNote) {
  const realm = getActiveRealmConfig();
  if (!getRealmDinosaurs().length && realm.emptyTitle) {
    return {
      title: realm.emptyTitle,
      note: realm.emptyNote || `${realm.label} 대표 생물을 검토한 뒤 공개합니다.`,
    };
  }
  return {
    title: `조건에 맞는 ${realm.label} 생물이 없습니다`,
    note: filteredNote,
  };
}

function renderClassificationTabs() {
  const baseMatches = getRealmDinosaurs().filter(matchesNonClassificationFilters);
  const counts = new Map(
    classificationGroups.map((group) => [
      group.id,
      baseMatches.filter((dino) => matchesClassification(dino, group.id)).length,
    ]),
  );

  $$('[data-classification-tabs] [data-classification]').forEach((button) => {
    const active = button.dataset.classification === state.classification;
    const countValue = counts.get(button.dataset.classification) ?? 0;
    const visible = button.dataset.classification === "all" || countValue > 0 || active;
    button.hidden = !visible;
    button.setAttribute("aria-hidden", String(!visible));
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", String(active));
    const count = button.querySelector("[data-classification-count]");
    if (count) count.textContent = countValue;
  });
}

function centerActiveClassificationTab(strip, behavior = "smooth") {
  if (!strip) return;
  const button = strip.querySelector(`[data-classification="${state.classification}"]`);
  if (!button) return;
  const targetLeft = button.offsetLeft - (strip.clientWidth - button.offsetWidth) / 2;
  strip.scrollTo({ left: Math.max(0, targetLeft), behavior });
}

function getDinoById(id) {
  return dinosaurs.find((dino) => dino.id === id);
}

function getFilteredIdSet() {
  return new Set(getFilteredDinosaurs().map((dino) => dino.id));
}

function getSelectedDino() {
  const filtered = getFilteredDinosaurs();
  const realmDinosaurs = getRealmDinosaurs();
  return (
    filtered.find((dino) => dino.id === state.selectedId) ||
    filtered[0] ||
    realmDinosaurs[0] ||
    null
  );
}

function getTaxonomyPath(dino) {
  return [dino.rootClade || "Dinosauria", dino.clade, dino.family].filter(Boolean).join(" / ");
}

function renderMetrics() {
  const filtered = getFilteredDinosaurs();
  const levels = [...new Set(filtered.map((dino) => dino.knowledgeLevel))].sort((a, b) => a - b);
  $("#metricSpecies").textContent = filtered.length;
  $("#metricClades").textContent = new Set(filtered.map((dino) => dino.clade)).size;
  $("#metricLevels").textContent = levels.length
    ? levels.length === 1
      ? `LV${levels[0]}`
      : `LV${levels[0]}-${levels[levels.length - 1]}`
    : "-";
  $("#metricImages").textContent = filtered.reduce((sum, dino) => sum + getGalleryItems(dino).length, 0);
}

function renderPeriodBands() {
  const layoutHeight = currentPhyloLayout.height || canvasSize.height;
  const layoutEras = currentPhyloLayout.eras || getActiveRealmEras();
  const filteredIds = getFilteredIdSet();
  $("#periodBands").innerHTML = layoutEras
    .map((era, index) => {
      const nextEra = layoutEras[index + 1];
      const height = nextEra ? era.height : Math.max(era.height, layoutHeight - era.top);
      const visibleTaxaCount = currentPhyloLayout.nodes.filter(
        (node) =>
          node.type === "taxon" &&
          filteredIds.has(node.speciesId) &&
          getDinoById(node.speciesId)?.era === era.id,
      ).length;
      return `
        <section class="period-band ${era.id}" style="top: ${era.top}px; height: ${height}px;">
          <div class="period-label">
            <span class="period-label-copy">
              <strong>${era.label}</strong>
              <span class="period-range">${era.range}</span>
            </span>
            <span class="period-count">${visibleTaxaCount}종</span>
          </div>
        </section>
      `;
    })
    .join("");
}

function getNodeWidth(node) {
  return node.type === "group"
    ? phyloLayoutMetrics.groupWidth
    : phyloLayoutMetrics.taxonWidth;
}

function getNodeHeight() {
  return phyloLayoutMetrics.nodeHeight;
}

