function hexToRgb(hex) {
  const value = String(hex || "").replace("#", "").trim();
  if (!/^[0-9a-f]{6}$/i.test(value)) return null;
  return {
    r: parseInt(value.slice(0, 2), 16),
    g: parseInt(value.slice(2, 4), 16),
    b: parseInt(value.slice(4, 6), 16),
  };
}

function darkenRgb(rgb, amount = 34) {
  return {
    r: Math.max(12, rgb.r - amount),
    g: Math.max(16, rgb.g - amount),
    b: Math.max(20, rgb.b - amount),
  };
}

function rgbaFromHex(hex, alpha) {
  const rgb = hexToRgb(hex);
  if (!rgb) return `rgba(230, 196, 106, ${alpha})`;
  return `rgba(${rgb.r}, ${rgb.g}, ${rgb.b}, ${alpha})`;
}

function getTaxonPalette(dino) {
  const fallbackByFamily = {
    Ceratopsidae: { accent: "#55d6be", bg: "rgba(18, 48, 49, 0.86)", border: "rgba(85, 214, 190, 0.34)" },
    Tyrannosauridae: { accent: "#ff8e72", bg: "rgba(65, 34, 26, 0.86)", border: "rgba(255, 142, 114, 0.34)" },
    Spinosauridae: { accent: "#6cb9ff", bg: "rgba(27, 48, 68, 0.86)", border: "rgba(108, 185, 255, 0.34)" },
    Diplodocidae: { accent: "#9bd66f", bg: "rgba(38, 57, 31, 0.86)", border: "rgba(155, 214, 111, 0.34)" },
    Dromaeosauridae: { accent: "#d88cff", bg: "rgba(52, 36, 64, 0.86)", border: "rgba(216, 140, 255, 0.34)" },
    Alvarezsauridae: { accent: "#2ec7c9", bg: "rgba(28, 38, 45, 0.86)", border: "rgba(46, 199, 201, 0.34)" },
    Avimimidae: { accent: "#b58cff", bg: "rgba(43, 35, 55, 0.86)", border: "rgba(181, 140, 255, 0.34)" },
    Oviraptoridae: { accent: "#6bd28d", bg: "rgba(31, 45, 38, 0.86)", border: "rgba(107, 210, 141, 0.34)" },
    Caenagnathidae: { accent: "#d0a11e", bg: "rgba(37, 43, 34, 0.86)", border: "rgba(208, 161, 30, 0.34)" },
    Ornithomimidae: { accent: "#64b7d8", bg: "rgba(28, 48, 58, 0.86)", border: "rgba(100, 183, 216, 0.34)" },
    Therizinosauridae: { accent: "#d94a45", bg: "rgba(47, 35, 43, 0.86)", border: "rgba(217, 74, 69, 0.34)" },
    Hadrosauridae: { accent: "#e1783f", bg: "rgba(40, 53, 35, 0.86)", border: "rgba(225, 120, 63, 0.34)" },
  };
  const directPalette = taxonPaletteAccents[dino.id];
  if (directPalette) return directPalette;

  const swatches = taxonPaletteSwatches[dino.id];
  if (swatches?.length) {
    const accent = swatches[0];
    const anchor = hexToRgb(swatches[1] || accent) || hexToRgb(accent);
    const bg = anchor ? darkenRgb(anchor, 18) : { r: 38, g: 43, b: 48 };
    return {
      accent,
      bg: `rgba(${bg.r}, ${bg.g}, ${bg.b}, 0.9)`,
      border: rgbaFromHex(accent, 0.46),
    };
  }

  return fallbackByFamily[dino.family] || {
    accent: "#e6c46a",
    bg: "rgba(38, 43, 48, 0.86)",
    border: "rgba(230, 196, 106, 0.3)",
  };
}

function getDinoPaletteStyle(dino) {
  const palette = getTaxonPalette(dino);
  const swatches = getDinoPaletteSwatches(dino);
  const wash = rgbaFromHex(swatches[0], 0.28);
  const washAlt = rgbaFromHex(swatches[2] || swatches[1] || swatches[0], 0.2);
  return `--taxon-accent: ${palette.accent}; --taxon-bg: ${palette.bg}; --taxon-border: ${palette.border}; --taxon-wash: ${wash}; --taxon-wash-alt: ${washAlt};`;
}

function getDinoPaletteSwatches(dino) {
  const basePalette = getTaxonPalette(dino).accent;
  return taxonPaletteSwatches[dino.id] || [basePalette, "#3e4a46", "#9fbf8d", "#d8bd79"];
}

function renderDinoPaletteSwatches(dino, className = "palette-strip") {
  const swatches = getDinoPaletteSwatches(dino);
  return `
    <div class="${className}" aria-label="\uc885\ubcc4 \uc0c9 \ubc30\ub9ac\uc5d0\uc774\uc158">
      ${swatches
        .map((color) => `<span class="palette-swatch" style="background: ${color};" title="${color}"></span>`)
        .join("")}
    </div>
  `;
}

function getTimelinePeriodMeta(period, eraId) {
  const knownPeriod = timelinePeriodOrder.find((item) => item.label === period);
  if (knownPeriod) {
    return {
      ...knownPeriod,
      order: timelinePeriodOrder.indexOf(knownPeriod),
    };
  }

  const eraIndex = Math.max(0, getActiveRealmEras().findIndex((era) => era.id === eraId));
  return {
    id: `other-${eraId || "unknown"}`,
    label: period || "시기 미상",
    era: eraId,
    order: eraIndex * 100 + 90,
  };
}

function compareTimelineDinosaurs(a, b) {
  const periodA = getTimelinePeriodMeta(a.period, a.era);
  const periodB = getTimelinePeriodMeta(b.period, b.era);
  return (
    periodA.order - periodB.order ||
    getPhyloCladeOrderIndex(a.clade) - getPhyloCladeOrderIndex(b.clade) ||
    a.clade.localeCompare(b.clade) ||
    a.family.localeCompare(b.family) ||
    a.koreanName.localeCompare(b.koreanName, "ko") ||
    a.id.localeCompare(b.id)
  );
}

function getTimelineBrowseDinosaurs() {
  const filtered = getFilteredDinosaurs();
  if (
    filtered.length > 0 &&
    state.map.scope !== "all" &&
    !filtered.some((dino) => dino.era === state.map.scope)
  ) {
    state.map.scope = filtered[0].era;
  }

  return filtered
    .filter((dino) => state.map.scope === "all" || dino.era === state.map.scope)
    .sort(compareTimelineDinosaurs);
}

function renderTimelineBrowse() {
  const container = $("#timelineBrowse");
  if (!container) return;

  const visibleDinosaurs = getTimelineBrowseDinosaurs();
  if (
    visibleDinosaurs.length > 0 &&
    !visibleDinosaurs.some((dino) => dino.id === state.selectedId)
  ) {
    state.selectedId = visibleDinosaurs[0].id;
    state.galleryIndex = 0;
  }

  if (visibleDinosaurs.length === 0) {
    const empty = getRealmEmptyStateCopy("검색어나 필터를 바꿔 보세요.");
    container.innerHTML = `
      <div class="timeline-empty">
        <strong>${escapeHtml(empty.title)}</strong>
        <span>${escapeHtml(empty.note)}</span>
      </div>
    `;
    return;
  }

  const grouped = new Map();
  visibleDinosaurs.forEach((dino) => {
    const meta = getTimelinePeriodMeta(dino.period, dino.era);
    const group = grouped.get(meta.label) || { meta, dinosaurs: [] };
    group.dinosaurs.push(dino);
    grouped.set(meta.label, group);
  });

  container.innerHTML = [...grouped.values()]
    .sort((a, b) => a.meta.order - b.meta.order)
    .map(({ meta, dinosaurs: periodDinosaurs }) => {
      const eraLabel = getEraLabel(meta.era) || "지질시대";
      const cards = periodDinosaurs
        .map((dino) => {
          const level = getKnowledgeLevel(dino.knowledgeLevel);
          const active = dino.id === state.selectedId;
          return `
            <button
              class="timeline-card ${active ? "active" : ""}"
              data-timeline-id="${escapeHtml(dino.id)}"
              type="button"
              aria-pressed="${String(active)}"
              aria-label="${escapeHtml(`${dino.koreanName} · ${dino.period}`)}"
              style="${getDinoPaletteStyle(dino)}"
            >
              <span class="timeline-card-kind">${escapeHtml(dino.clade)}</span>
              <strong>${escapeHtml(dino.koreanName)}</strong>
              <span class="timeline-card-name">${escapeHtml(dino.name)}</span>
              <span class="timeline-card-meta">
                <span>${escapeHtml(dino.family)}</span>
                <span class="level-badge level-${dino.knowledgeLevel}" title="${escapeHtml(level.description)}" aria-label="${escapeHtml("친숙도 " + level.short + " " + level.label)}">${escapeHtml(level.short)}</span>
              </span>
              ${renderDinoPaletteSwatches(dino, "palette-strip timeline-palette")}
            </button>
          `;
        })
        .join("");

      return `
        <section class="timeline-period-section" data-timeline-period="${escapeHtml(meta.id)}">
          <header class="timeline-period-heading">
            <div>
              <p class="eyebrow">${escapeHtml(eraLabel)}</p>
              <h3>${escapeHtml(meta.label)}</h3>
            </div>
            <span class="timeline-period-count">${periodDinosaurs.length}종</span>
          </header>
          <div class="timeline-grid">${cards}</div>
        </section>
      `;
    })
    .join("");
}

