  "Radiodonta",
  "Placodermi",
  "Lamniformes",
  "Theropoda",
  "Avialae",
  "Sauropodomorpha",
  "Ornithopoda",
  "Ceratopsia",
  "Ankylosauria",
  "Pachycephalosauria",
  "Thyreophora",
  "Sphenacodontia",
  "Dicynodontia",
